 /** Whether one rule applies to a request. See README.md. */
 export function matches(rule: Rule, request: AccessRequest): boolean {
-  throw new Error("not implemented");
+  const roleMatch = rule.role === "*" || request.roles.includes(rule.role);
+  const actionMatch = rule.action === "*" || rule.action === request.action;
+  let resourceMatch: boolean;
+  if (rule.resource === "*") {
+    resourceMatch = true;
+  } else if (rule.resource.endsWith("/*")) {
+    const prefix = rule.resource.slice(0, -1);
+    resourceMatch = request.resource.startsWith(prefix);
+  } else {
+    resourceMatch = rule.resource === request.resource;
+  }
+  return roleMatch && actionMatch && resourceMatch;
 }

 /** Decide a request against an ordered rule list. */
 export function isAllowed(rules: Rule[], request: AccessRequest): boolean {
-  throw new Error("not implemented");
+  return explain(rules, request).allowed;
 }

 /** Decide a request and say which rule decided it. */
 export function explain(rules: Rule[], request: AccessRequest): Decision {
-  throw new Error("not implemented");
+  let lastMatch: Rule | undefined;
+  for (const rule of rules) {
+    if (matches(rule, request)) {
+      lastMatch = rule;
+    }
+  }
+  if (!lastMatch) return { allowed: false, rule: undefined };
+  return { allowed: lastMatch.effect === "allow", rule: lastMatch };
 }

 /** The candidate actions a role set may perform on a resource. */
